let inputString = "";
let currentLine = 0;
process.stdin.on("data", (data) => {
  inputString += data;
});
process.stdin.on("end", function () {
  inputString = inputString
    .trim()
    .split("\n")
    .map((str) => str.trim());
  main();
});
function readLine() {
  return inputString[currentLine++];
}
function main() {
  let a = readLine();
  if (a.toUpperCase() === a) {
    console.log(a.toLowerCase());
  } else if (a[0].toLowerCase() + a.substring(1).toUpperCase() === a) {
    console.log(a[0].toUpperCase() + a.substring(1).toLowerCase());
  } else {
    console.log(a);
  }
}
